        bankPortal = softwareSystem "Bank Portal" "The online banking platform owned and operated by the bank, where customers manage their accounts, move money, and track their activity." {

            webPortal = container "Web Portal" "Where customers log in and manage their accounts." "Web application" "Web"
            mobileAppBackend = container "Mobile App Backend" "Serves the bank's mobile app." "API service"
            accountService = container "Account Service" "Holds the customer account records." "Microservice"
            transactionService = container "Transaction Service" "Processes deposits, withdrawals, and transfers." "Microservice"
            paymentService = container "Payment Service" "Executes card payments and bank transfers." "Microservice"
            cardService = container "Card Service" "Manages debit and credit cards." "Microservice"
            fraudDetectionService = container "Fraud Detection Service" "Scores transactions for fraud." "Microservice"
            notificationService = container "Notification Service" "Sends email and SMS alerts." "Microservice"
            onboardingService = container "Onboarding Service" "Verifies new customers." "Microservice"
            statementsService = container "Statements Service" "Generates monthly statements." "Microservice"
            directDebitService = container "Direct Debit Service" "Processes standing orders and direct debits." "Microservice"
            exchangeRatesService = container "Exchange Rates Service" "Provides currency conversion rates." "Microservice"
            batchScheduler = container "Batch Scheduler" "Runs the nightly interest calculation and reconciliation." "Batch job"
            eventQueue = container "Event Queue" "Carries internal events between the application parts." "Message queue" "Queue"
            ledgerDb = container "Ledger Database" "Stores every account movement." "Relational database" "Database"
            customerDb = container "Customer Database" "Stores account and profile records." "Relational database" "Database"
            auditDb = container "Audit Database" "Stores the compliance audit trail." "Relational database" "Database"
            cache = container "Cache" "Stores sessions and frequently read account data." "In-memory cache"
            documentStore = container "Document Store" "Holds the generated statement PDFs." "Document store"
        }

        cardPaymentNetwork = softwareSystem "Card Payment Network" "Routes card authorisations; operated by a different organization." "External"
        creditReferenceAgency = softwareSystem "Credit Reference Agency" "Performs credit checks; operated by a different organization." "External"

        customer -> webPortal "Logs in and manages accounts" "HTTPS/JSON"
        customer -> mobileAppBackend "Uses the mobile app" "HTTPS/JSON"

        webPortal -> accountService "Manages customer accounts" "HTTPS/JSON"
        webPortal -> transactionService "Processes deposits, withdrawals and transfers" "HTTPS/JSON"
        webPortal -> paymentService "Executes card payments and bank transfers" "HTTPS/JSON"
        webPortal -> cardService "Manages debit and credit cards" "HTTPS/JSON"
        webPortal -> statementsService "Generates monthly statements" "HTTPS/JSON"
        webPortal -> directDebitService "Processes standing orders and direct debits" "HTTPS/JSON"

        mobileAppBackend -> accountService "Manages customer accounts" "HTTPS/JSON"
        mobileAppBackend -> transactionService "Processes deposits, withdrawals and transfers" "HTTPS/JSON"
        mobileAppBackend -> paymentService "Executes card payments and bank transfers" "HTTPS/JSON"
        mobileAppBackend -> cardService "Manages debit and credit cards" "HTTPS/JSON"
        mobileAppBackend -> statementsService "Generates monthly statements" "HTTPS/JSON"
        mobileAppBackend -> directDebitService "Processes standing orders and direct debits" "HTTPS/JSON"

        transactionService -> ledgerDb "Updates the ledger" "SQL"
        transactionService -> fraudDetectionService "Scores transactions for fraud" "HTTPS/JSON"
        transactionService -> eventQueue "Publishes events to" "AMQP"

        notificationService -> eventQueue "Consumes events from" "AMQP"

        statementsService -> ledgerDb "Reads account movements from" "SQL"
        statementsService -> documentStore "Writes statement PDFs to" "Object storage"

        batchScheduler -> ledgerDb "Reads and writes the ledger" "SQL"
        batchScheduler -> customerDb "Reads and writes customer records" "SQL"

        paymentService -> cardService "Requests card authorisations" "HTTPS/JSON"
        paymentService -> exchangeRatesService "Requests currency conversion rates" "HTTPS/JSON"

        onboardingService -> customerDb "Reads customer records from" "SQL"

        paymentService -> cardPaymentNetwork "Routes card authorisations through" "ISO 8583"
        onboardingService -> creditReferenceAgency "Performs credit checks through" "HTTPS/JSON"
    }

    views {

        systemContext bankPortal "SystemContext" {
            include *
            autoLayout
            title "System Context for Bank Portal"
        }

        container bankPortal "Containers" {
            include *
            autoLayout
            title "Containers for Bank Portal"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
