                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Web" {
                shape WebBrowser
            }
            element "Queue" {
                shape Pipe
            }
            relationship "Relationship" {
                routing Orthogonal
            }
        }
    }

    configuration {
        scope softwaresystem
    }
}
`
});"}

